<script setup>
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { useI18n } from 'vue-i18n'
import { eventsApi } from '../api/events.js'
import EventStream from '../components/EventStream.vue'
import { eventMedia } from '../utils/eventMedia.js'
const route = useRoute(), { locale } = useI18n()
const tr = (en, fa) => locale.value === 'fa' ? fa : en
const room = ref(null), error = ref(''), busy = ref(false), chat = ref(''), question = ref(''), tab = ref('questions')
let timer = null, sequence = 0, stopped = false
const refresh = async () => {
  const request = ++sequence
  try {
    const response = await eventsApi.live(route.params.slug, locale.value)
    if (!stopped && request === sequence) { room.value = response.data; error.value = '' }
  } catch (problem) {
    if (!stopped && request === sequence) { error.value = problem.message; if ([401,403,404,409].includes(problem.status)) room.value = null }
  }
}
const poll = async () => { if (!document.hidden) await refresh(); if (!stopped) timer = window.setTimeout(poll, 5000) }
onMounted(poll)
onUnmounted(() => { stopped = true; sequence++; window.clearTimeout(timer) })
watch([() => route.params.slug, locale], () => { room.value = null; refresh() })
const stream = computed(() => eventMedia(room.value?.event?.online_url))
const conversationClosed = computed(() => room.value?.event.status !== 'live' || !(tab.value === 'chat' ? room.value?.chat_enabled : room.value?.questions_enabled))
const submit = async (kind) => { const value = kind === 'chat' ? chat.value : question.value; if (!value.trim() || busy.value || conversationClosed.value) return; busy.value = true; try { await (kind === 'chat' ? eventsApi.liveMessage(route.params.slug, value) : eventsApi.liveQuestion(route.params.slug, value)); if (kind === 'chat') chat.value = ''; else question.value = ''; await refresh() } catch (problem) { error.value = problem.message } finally { busy.value = false } }
const action = async (fn) => { try { await fn(); await refresh() } catch (problem) { error.value = problem.message } }
const sortedQuestions = computed(() => [...(room.value?.questions || [])].sort((a, b) => Number(a.answered) - Number(b.answered) || b.votes - a.votes))
const countryCount = computed(() => Object.keys(room.value?.countries || {}).filter((key) => key !== '--').length)
</script>
<template>
  <main class="min-h-screen bg-ink text-parchment-light"><div class="mx-auto max-w-7xl px-5 py-10 md:px-8"><router-link to="/events" class="text-xs uppercase tracking-[.22em] text-gold">{{ tr('← All events', 'بازگشت به رویدادها ←') }}</router-link><div v-if="error" role="alert" class="mt-6 rounded-lg border border-red-400/40 bg-red-950/30 p-4 text-sm text-red-200">{{ error }}<router-link v-if="!room" :to="`/events/reserve/online/${route.params.slug}`" class="ms-4 underline">{{ tr('Reserve a place', 'رزرو رویداد') }}</router-link></div><div v-if="room"><div class="mt-9 flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs uppercase tracking-[.3em] text-gold">{{ room.event.status === 'live' ? tr('● LIVE EVENT', '● رویداد زنده') : tr('EVENT ROOM', 'اتاق رویداد') }}</p><h1 class="mt-3 font-serif text-3xl md:text-5xl">{{ room.event.title }}</h1></div><div class="flex gap-5 text-xs uppercase tracking-[.17em] text-parchment-light/65"><span>{{ room.viewer_count }} {{ tr('viewers', 'نفر حاضر') }}</span><span>{{ countryCount }} {{ tr('countries', 'کشور') }}</span><span>{{ room.question_count }} {{ tr('questions', 'سؤال') }}</span></div></div>
      <div class="mt-8 grid gap-6 lg:grid-cols-[minmax(0,1.7fr)_minmax(310px,1fr)]"><div><div class="aspect-video overflow-hidden rounded-xl border border-gold/20 bg-black"><EventStream v-if="stream" :url="room.event.online_url" :title="room.event.title" /><div v-else class="flex h-full items-center justify-center text-center text-parchment-light/50">{{ room.event.status === 'live' ? tr('Stream link is not available yet.', 'لینک پخش هنوز ثبت نشده است.') : tr('The live stream has not started.', 'پخش زنده هنوز آغاز نشده است.') }}</div></div><a v-if="stream?.type === 'video'" :href="stream.src" target="_blank" rel="noopener noreferrer" class="mt-3 inline-block text-xs text-gold underline">{{ tr('Open stream in another player', 'باز کردن پخش در پلیر دیگر') }}</a><section class="mt-7 rounded-xl border border-gold/15 bg-white/5 p-6"><div class="flex items-center justify-between"><h2 class="font-serif text-2xl">{{ tr('Session steps', 'مراحل برنامه') }}</h2><span class="text-xs text-gold">{{ room.event.agenda_steps.length ? room.event.current_step + 1 : 0 }} / {{ room.event.agenda_steps.length }}</span></div><p v-if="!room.event.agenda_steps.length" class="mt-5 text-sm text-parchment-light/55">{{ tr('Agenda will appear here.', 'برنامهٔ رویداد اینجا نمایش داده می‌شود.') }}</p><ol class="mt-5 space-y-2"><li v-for="(step, index) in room.event.agenda_steps" :key="index"><button type="button" :disabled="!room.instructor || room.event.status !== 'live'" class="flex w-full items-center gap-4 rounded-lg p-3 text-start" :class="index === room.event.current_step ? 'bg-gold/15 text-gold' : 'text-parchment-light/50'" @click="room.instructor && action(() => eventsApi.liveStep(route.params.slug, index))"><span class="w-8 text-xs">{{ index < room.event.current_step ? '✓' : String(index + 1).padStart(2,'0') }}</span><span>{{ step }}</span></button></li></ol></section><section class="mt-5 rounded-xl border border-gold/15 bg-white/5 p-5"><h2 class="text-sm uppercase tracking-[.2em] text-gold">{{ tr('Audience by country', 'حاضران بر اساس کشور') }}</h2><div class="mt-4 flex flex-wrap gap-2"><span v-for="(count, country) in room.countries" :key="country" class="rounded-full border border-gold/20 px-3 py-1 text-xs">{{ country === '--' ? tr('Unknown', 'نامشخص') : country }} · {{ count }}</span></div></section></div>
      <aside class="flex min-h-[35rem] flex-col rounded-xl border border-gold/20 bg-white/5"><div class="flex border-b border-gold/15"><button v-for="item in ['questions','chat']" :key="item" type="button" class="flex-1 px-4 py-4 text-xs uppercase tracking-[.2em]" :class="tab === item ? 'border-b-2 border-gold text-gold' : 'text-parchment-light/55'" @click="tab=item">{{ item === 'questions' ? tr('Questions', 'سؤال‌ها') : tr('Chat', 'گفت‌وگو') }}</button></div><div class="max-h-[32rem] flex-1 space-y-3 overflow-y-auto p-4"><template v-if="tab === 'questions'"><article v-for="item in sortedQuestions" :key="item.id" class="rounded-lg bg-black/20 p-4"><div class="flex items-center justify-between text-[11px] text-parchment-light/50"><span>{{ item.author }}</span><span v-if="item.answered" class="text-gold">{{ tr('Answered', 'پاسخ‌داده‌شده') }}</span></div><p class="mt-2 text-sm leading-6">{{ item.body }}</p><div class="mt-3 flex items-center justify-between"><button type="button" class="text-xs" :class="item.voted ? 'text-gold' : 'text-parchment-light/55'" :disabled="room.event.status !== 'live' || !room.questions_enabled" @click="action(() => eventsApi.liveVote(route.params.slug, item.id))">▲ {{ item.votes }}</button><button v-if="room.instructor && !item.answered && room.event.status === 'live'" type="button" class="text-xs text-gold" @click="action(() => eventsApi.liveAnswer(route.params.slug, item.id))">{{ tr('Mark answered', 'علامت پاسخ') }}</button></div></article></template><template v-else><div v-for="item in room.messages" :key="item.id" class="rounded-lg bg-black/20 p-3"><span class="text-xs text-gold">{{ item.author }}</span><p class="mt-1 text-sm leading-6">{{ item.body }}</p></div></template></div><form class="border-t border-gold/15 p-4" @submit.prevent="submit(tab)"><p v-if="conversationClosed" class="mb-2 text-xs text-parchment-light/55">{{ tr('Conversation is paused.', 'گفت‌وگو فعلاً بسته است.') }}</p><label class="sr-only" for="live-text">{{ tab === 'chat' ? tr('Message', 'پیام') : tr('Question', 'سؤال') }}</label><textarea id="live-text" v-if="tab === 'questions'" v-model="question" maxlength="1000" rows="2" class="w-full rounded-lg border border-gold/20 bg-black/20 p-3 text-sm outline-none focus:border-gold" :placeholder="tr('Ask a question…', 'سؤال خود را بپرسید…')"></textarea><textarea id="live-text" v-else v-model="chat" maxlength="1000" rows="2" class="w-full rounded-lg border border-gold/20 bg-black/20 p-3 text-sm outline-none focus:border-gold" :placeholder="tr('Write a message…', 'پیام خود را بنویسید…')"></textarea><button type="submit" :disabled="busy || conversationClosed" class="mt-2 rounded-lg bg-gold px-5 py-2 text-xs uppercase tracking-[.18em] text-ink disabled:opacity-40">{{ tr('Send', 'ارسال') }}</button></form></aside></div></div></div></main>
</template>

